    <h3>Realism Flags</h3>
    <div class="checkbox-group">
      <label><input type="checkbox" class="flag-check" value="Too Polished"> Too Polished</label>
      <label><input type="checkbox" class="flag-check" value="Too Vague"> Too Vague</label>
